{
  "positionId": "P08",
  "interviews": [
    {
      "categoryId": "P08-C1",
      "itemId": "P08-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "관리자 화면의 반복 요소와 화면별 차이를 구분하고, 재사용과 변경 용이성을 고려해 컴포넌트 경계와 상태 관리 방식을 설계·구현한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "관리자 화면에서 반복되는 테이블·필터의 구성과 화면별로 달랐던 요구사항을 설명한다.",
          "task": "공통으로 재사용할 부분과 개별 화면에서 제어할 부분을 구분해야 했던 과제를 설명한다.",
          "action": "반복 요소를 컴포넌트로 나눈 기준, 외부 입력과 내부 상태의 구분, 상태의 소유 위치와 변경 흐름을 실제 구현에 연결해 설명한다.",
          "result": "공통 컴포넌트를 적용한 뒤 재사용이나 화면별 요구사항 변경에 어떤 영향이 있었는지 구체적인 사례로 설명한다."
        },
        "expectedEvidence": [
          "화면의 반복 요소와 개별 요구사항을 비교해 공통화 범위를 정한 근거",
          "컴포넌트 경계를 재사용과 변경 용이성 관점에서 정한 이유",
          "외부에서 제어할 값과 내부에서 관리할 상태를 구분한 방식 및 이유",
          "설계한 구조를 실제 화면에 적용한 구현 내용과 재사용·변경 대응 결과"
        ]
      },
      "question": "배움노트 관리자 페이지의 테이블·필터를 공통화할 때, 화면의 반복 요소와 상태를 어떤 기준으로 나누어 재사용과 변경에 대응했는지 설명해 주세요.",
      "answerTip": "본인이 맡았던 사례를 차분히 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "반복 요소와 화면별 차이를 구체적으로 비교하고, 컴포넌트 분리 기준을 재사용 및 변경 용이성과 연결해 설명한다.",
            "외부 입력과 내부 상태의 경계, 상태 소유 위치 및 변경 흐름을 실제 구현에 근거해 설명한다.",
            "공통 컴포넌트 적용 후 재사용하거나 요구사항을 변경한 사례를 통해 설계의 결과를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "공통화한 요소와 컴포넌트 분리 이유는 설명하지만, 화면별 차이에 대응하는 구조의 설명이 일부 부족하다.",
            "외부 제어와 내부 상태 관리 방식은 확인되지만, 구분 근거나 변경 흐름이 충분히 구체적이지 않다.",
            "실제 적용 경험은 확인되지만, 재사용이나 변경 대응 결과에 대한 설명이 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "공통화했다는 사실만 언급하고 반복 요소를 식별하거나 컴포넌트를 나눈 기준을 설명하지 못한다.",
            "상태 관리 방식과 컴포넌트 구조에 대한 본인의 구현 근거가 확인되지 않는다.",
            "재사용·변경 대응과 무관한 성능 개선 등의 설명에 머물러 해당 설계 역량을 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P08-C1",
      "itemId": "P08-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "모바일·PC에 맞는 반응형 화면을 구현하고, 브라우저·기기별 차이를 직접 재현·보정하여 일관된 사용 경험을 확보한 과정을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "런메이트의 모바일·PC 화면 요구사항과 배움노트에서 발생했던 Safari 날짜 입력 문제의 환경 및 증상을 설명한다.",
          "task": "화면 크기에 맞게 레이아웃을 조정하고 브라우저별 차이를 보정하여 사용 흐름을 유지해야 했던 과제를 설명한다.",
          "action": "반응형 레이아웃 구현 방식과 화면 크기별 확인 과정, Safari 문제를 재현한 조건, 원인에 따른 수정 및 재확인 과정을 설명한다.",
          "result": "대응 전후 화면과 동작이 어떻게 달라졌으며, 모바일·PC 및 관련 브라우저 환경에서 의도한 사용 경험이 유지되는지 확인한 결과를 설명한다."
        },
        "expectedEvidence": [
          "모바일·PC 화면 크기에 따라 레이아웃을 조정한 구체적인 구현 방식",
          "화면 크기별 표시와 동작을 직접 확인한 과정",
          "브라우저·기기별 문제의 발생 환경과 재현 조건",
          "재현한 차이에 대한 보정 내용과 수정 후 재확인 결과",
          "환경이 달라도 핵심 사용 흐름이 유지되는지 확인한 근거"
        ]
      },
      "question": "런메이트의 모바일·PC 레이아웃과 배움노트의 Safari 날짜 입력 대응 경험을 바탕으로, 환경별 화면·동작 차이를 확인하고 보정한 과정을 설명해 주세요.",
      "answerTip": "경험의 흐름에 따라 차분히 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "모바일·PC 요구에 맞춘 반응형 구현 방식과 화면 크기별 확인 과정을 구체적으로 설명한다.",
            "Safari 문제의 발생 환경과 재현 조건을 밝히고, 확인한 원인에 연결해 보정 내용을 설명한다.",
            "수정 후 관련 환경에서 다시 확인한 결과를 제시하여 화면과 핵심 사용 흐름의 일관성을 입증한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "반응형 구현 또는 브라우저 차이 대응의 실제 행동은 확인되지만, 두 영역 중 일부의 설명이 부족하다.",
            "환경별 확인과 수정 과정은 설명하지만, 재현 조건이나 보정 근거가 충분히 구체적이지 않다.",
            "대응 결과는 제시하지만, 관련 환경에서의 재확인이나 사용 흐름의 일관성을 뒷받침하는 근거가 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "반응형이나 브라우저 호환성의 일반적인 설명에 머물러 실제 구현·확인 행동이 드러나지 않는다.",
            "환경별 차이를 직접 재현하거나 확인한 근거와 구체적인 보정 내용을 제시하지 못한다.",
            "수정 후 동작 확인에 대한 근거가 없어 환경별로 일관된 경험을 제공했는지 판단하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P08",
  "interviews": [
    {
      "categoryId": "P08-C2",
      "itemId": "P08-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "출결 API 연동 경험을 통해 비동기 요청의 흐름과 화면 상태를 설계하고, 로딩·실패·빈 데이터 상황에서도 사용자에게 잘못된 정보를 보여 주지 않도록 구현했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "출결 API를 연동한 화면의 용도와 요청 중이거나 실패했을 때, 결과가 비어 있을 때 발생할 수 있었던 사용자 혼란을 설명한다.",
          "task": "요청 진행 상태와 응답 결과를 구분하고, 각 상태에서 화면이 멈추거나 부정확한 출결 정보를 표시하지 않도록 해야 했던 본인의 역할을 설명한다.",
          "action": "요청 시작·성공·실패에 따른 데이터와 화면 상태 전환을 어떻게 구현했는지 설명하고, 로딩·오류·빈 목록을 구분해 표시한 방식과 그 이유를 제시한다.",
          "result": "각 상태를 확인한 방법과 실제 화면 동작을 설명하고, 사용자가 대기·실패·데이터 없음을 구분할 수 있었는지 및 잘못된 정보 표시를 방지했는지 제시한다."
        },
        "expectedEvidence": [
          "API 요청 시작부터 응답 또는 실패까지 데이터와 화면 상태가 전환되는 구체적인 흐름",
          "로딩 중·요청 실패·정상 응답의 빈 데이터를 서로 구분하는 조건과 화면 처리 방식",
          "요청 처리 중 화면이 멈추거나 이전 데이터 등이 잘못된 정보로 표시되지 않도록 한 구현",
          "상태별 화면 동작을 확인한 방법과 사용자에게 나타난 결과"
        ]
      },
      "question": "배움노트에서 출결 API를 연동할 때, 로딩·실패·빈 목록 상황에서 화면이 멈추거나 잘못된 정보를 보여 주지 않도록 데이터 흐름과 화면 상태를 어떻게 구현했나요?",
      "answerTip": "본인이 맡았던 사례를 차분히 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "출결 화면의 상황과 본인의 역할을 밝히고, 요청 시작·성공·실패에 따른 데이터 및 화면 상태 전환을 구체적으로 설명한다.",
            "로딩·실패·빈 데이터를 구분하는 조건과 표시 방식을 사용자 혼란 방지 관점에서 설명하고, 화면 멈춤이나 잘못된 정보 표시를 방지한 구현을 제시한다.",
            "상태별 확인 방법과 실제 화면 동작을 제시하여 의도한 처리가 이루어졌음을 입증한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "비동기 요청에 따른 상태 전환과 로딩·실패·빈 데이터 처리의 핵심 방식은 설명하지만, 일부 전환 조건이나 구현 설명이 부족하다.",
            "사용자 혼란이나 잘못된 정보 표시를 방지하려는 처리는 확인되지만, 상태별 동작 확인 방법 또는 결과가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "API를 연결했다는 설명에 그쳐 요청 흐름과 화면 상태 전환을 확인하기 어렵다.",
            "로딩·실패·빈 데이터를 구분하지 않거나, 화면 멈춤과 잘못된 정보 표시를 방지하는 처리에 대한 근거가 부족하다.",
            "본인의 구현이나 상태별 화면 동작을 설명하지 못하고 일반적인 원칙만 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P08-C2",
      "itemId": "P08-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "수강생 목록 화면의 성능 개선 경험을 통해 도구로 병목을 측정·분석하고, 원인에 대응한 조치의 효과를 전후 재측정으로 입증했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배움노트 수강생 목록 화면의 초기 로딩이 느렸던 상황과 개선 대상으로 삼은 로딩 시간의 측정 범위를 설명한다.",
          "task": "느린 초기 로딩의 원인을 측정으로 파악하고, 개선 후 동일한 지표로 효과를 확인해야 했던 본인의 역할을 설명한다.",
          "action": "Lighthouse와 네트워크 탭에서 확인한 측정값이나 관찰 내용을 바탕으로 병목을 분석하고, 코드 스플리팅과 이미지 지연 로딩을 선택한 이유 및 적용 과정을 설명한다.",
          "result": "초기 로딩 4.1초에서 1.6초로 단축했다는 결과가 어떤 측정 지표와 조건에서 나온 것인지 밝히고, 비교 가능한 조건의 재측정으로 개선 효과를 설명한다."
        },
        "expectedEvidence": [
          "성능 측정에 사용한 도구, 측정 대상 지표 및 측정 조건",
          "도구에서 관찰한 번들 또는 네트워크 요청 관련 근거와 병목 원인 사이의 연결",
          "확인한 병목 원인에 대응하는 개선 조치와 적용 이유",
          "동일한 지표와 비교 가능한 조건에서 측정한 개선 전후 결과"
        ]
      },
      "question": "배움노트 수강생 목록의 초기 로딩을 4.1초에서 1.6초로 줄인 경험에서, 측정한 병목을 바탕으로 개선하고 효과를 재확인한 과정을 설명해 주시겠어요?",
      "answerTip": "한 가지 경험을 흐름에 따라 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "사용한 도구와 로딩 지표의 의미, 측정 조건을 구체적으로 밝히고 관찰 결과를 병목 원인과 연결한다.",
            "코드 스플리팅과 이미지 지연 로딩 등 본인이 적용한 조치가 확인된 병목을 어떻게 줄였는지 설명한다.",
            "동일한 지표와 비교 가능한 조건으로 전후를 재측정한 결과를 제시하여 개선 효과를 입증한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "도구를 통한 병목 확인과 그에 대응한 개선 조치는 설명하지만, 관찰한 수치나 원인 분석 과정의 일부가 부족하다.",
            "전후 재측정과 성능 향상 결과는 제시하지만, 측정 지표의 의미나 비교 조건에 대한 설명이 불충분하다."
          ]
        },
        "poor": {
          "criteria": [
            "성능이 느렸다는 인상이나 최종 수치만 제시하고, 도구로 원인을 측정·분석한 근거를 설명하지 못한다.",
            "적용한 최적화 기법을 나열하지만 측정된 병목과 개선 조치의 연결이 확인되지 않는다.",
            "개선 후 재측정한 근거가 없어 전후 차이와 개선 효과를 확인하기 어렵다."
          ]
        }
      }
    }
